"""September 2014 Uber pickups in New York City, aggregated to a grid — the real dataset.

1,028,136 pickups from `streamlit/demo-uber-nyc-pickups`, which is FiveThirtyEight's release of
a New York City Taxi & Limousine Commission FOIL request. This module carries 998,189 of
them: the 98.2% inside the city, binned into 0.005-degree cells — about 550 by 420 metres —
dropping cells where fewer than two pickups happened all month at that hour.

The 6.8 MB CSV becomes 116 KB because no map can draw a million overlapping dots anyway.
Each hour is one base64 string of four-byte records — row, column, and the count as two bytes —
so a page decodes only the hour it is showing, about a thousand cells, and never touches the
other twenty-three. `cells()` and `histogram()` below are the only way in.
"""

import binascii

LAT0, LON0, STEP = 40.6, -74.1, 0.005
ROWS, COLS = 64, 79
TOTAL = 998189
PEAK_CELL = 1862

_decoded = {}


def raw(hour):
    """The hour's records as bytes, decoded once. Bytes rather than tuples on purpose: the
    histogram scans all twenty-four hours on every pan, and 22,449 Python tuples would not
    fit in the interpreter's megabyte, let alone be rebuilt each time."""
    got = _decoded.get(hour)
    if got is None:
        got = _decoded[hour] = binascii.a2b_base64(HOURS[hour])
    return got


def cells(hour):
    """`(lat, lon, count)` at the centre of every populated cell in that hour."""
    data = raw(hour)
    return [
        (LAT0 + (data[i] + 0.5) * STEP, LON0 + (data[i + 1] + 0.5) * STEP, (data[i + 2] << 8) | data[i + 3])
        for i in range(0, len(data), 4)
    ]


def histogram(south, west, north, east):
    """Pickups per hour of the day inside a bounding box — twenty-four numbers.

    Scanned straight out of the packed bytes, allocating nothing, because this runs every time
    the reader stops panning the map.
    """
    y0 = int((south - LAT0) / STEP)
    y1 = int((north - LAT0) / STEP)
    x0 = int((west - LON0) / STEP)
    x1 = int((east - LON0) / STEP)
    out = []
    for hour in range(24):
        data = raw(hour)
        total = 0
        for i in range(0, len(data), 4):
            if y0 <= data[i] <= y1 and x0 <= data[i + 1] <= x1:
                total += (data[i + 2] << 8) | data[i + 3]
        out.append(total)
    return out


